"""Snap clock times to a fixed step for payroll."""

from typing import Iterable

from hourglass.parsing import format_span
from hourglass.models import Span

def check_step(step: int) -> None:
    if step <= 0 or 60 % step:
        raise ValueError(f"bad step: {step!r}")

def snap_minutes(value: int, step: int) -> int:
    """Nearest multiple of step. Halfway rounds up."""
    return (value + step // 2) // step * step

def duration_text(span: Span) -> str:
    hours, extra = divmod(span.minutes, 60)
    return f"{hours}h {extra}m"

# ---
def round_span(span: Span, step: int) -> Span:
    """Snap both ends. Collapsing raises ValueError."""
    check_step(step)
    return Span(
        snap_minutes(span.start, step),
        snap_minutes(span.end, step)
    )

# ---
def round_labels(spans: Iterable[Span], step: int):
    """Labels such as 09:00-17:15 (8h 15m), one per span."""
    check_step(step)
    rounded = [round_span(item, step) for item in spans]
    return [
        f"{format_span(item)} ({duration_text(item)})"
        for item in rounded
    ]

