import unittest

from hourglass.rounding import round_labels, round_span
from hourglass.models import Span

class RoundSpanTests(unittest.TestCase):
    def test_snaps_to_nearest_step(self):
        result = round_span(Span(542, 1023), 15)
        self.assertEqual(result, Span(540, 1020))

    def test_halfway_rounds_up(self):
        result = round_span(Span(68, 128), 15)
        self.assertEqual(result, Span(75, 135))

    def test_end_can_reach_midnight(self):
        result = round_span(Span(600, 1439), 30)
        self.assertEqual(result, Span(600, 1440))

    def test_collapsed_span_raises(self):
        with self.assertRaises(ValueError):
            round_span(Span(541, 545), 15)

class LabelTests(unittest.TestCase):
    def test_label_format(self):
        labels = round_labels([Span(540, 1035)], 15)
        self.assertEqual(labels, ["09:00-17:15 (8h 15m)"])

    def test_one_label_per_span(self):
        spans = [Span(541, 601), Span(721, 782)]
        labels = round_labels(spans, 5)
        self.assertEqual(len(labels), 2)
        self.assertEqual(labels[1], "12:00-13:00 (1h 0m)")

    def test_empty_list(self):
        self.assertEqual(round_labels([], 15), [])

class BadStepTests(unittest.TestCase):
    def test_bad_steps_raise(self):
        for step in (0, -15, 7, 45, 120):
            with self.assertRaises(ValueError):
                round_labels([Span(60, 120)], step)

    def test_bad_step_raises_for_empty_list(self):
        with self.assertRaises(ValueError):
            round_labels([], 0)

    def test_good_steps_work(self):
        for step in (1, 5, 6, 10, 15, 20, 30, 60):
            result = round_labels([Span(0, 600)], step)
            self.assertEqual(len(result), 1)
